public.aip_consume_budget_as_actor_a0v_1.definition:
CREATE OR REPLACE FUNCTION public.aip_consume_budget_as_actor_a0v_127(p_org text, p_project text, p_proposal text, p_decision text, p_actor text, p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
    IF current_setting('transaction_read_only')<>'off'
       OR current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION 'BUDGET_CONSUMER_WRITE_TRANSACTION_REQUIRED' USING ERRCODE='42501';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('budget-cost-review:'||p_org||':'||p_project||':'||p_proposal,0));
    PERFORM public.aip_budget_cost_actor_a0v_127(p_org,p_project,p_proposal,p_actor,p_hash);
    RETURN public.aip_consume_budget_cost_a0v_126(p_org,p_project,p_proposal,p_decision);
END $function$

public.aip_consume_budget_cost_a0v_126(t.definition:
CREATE OR REPLACE FUNCTION public.aip_consume_budget_cost_a0v_126(p_org text, p_project text, p_proposal text, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  p public.aip_budget_cost_proposal%ROWTYPE; d public.aip_budget_cost_decision%ROWTYPE;
  h public.aip_budget_head%ROWTYPE; draft public.aip_budget_revision%ROWTYPE;
  source public.aip_provider_instance_revision%ROWTYPE; prior public.aip_budget_receipt%ROWTYPE;
  t jsonb; basis jsonb; ref jsonb; payload jsonb; result jsonb; expected jsonb;
  request_hash text; target_hash text; source_revision bigint; checked_at timestamptz; number_value jsonb;
BEGIN
  IF session_user<>'aos_budget_consumer_call' OR current_user<>'aos_budget_consumer_owner'
     OR p_org IS DISTINCT FROM 'org-org' OR p_project IS DISTINCT FROM 'dev-project'
     OR p_proposal IS NULL OR p_proposal='' OR p_proposal<>btrim(p_proposal)
     OR p_decision IS NULL OR p_decision='' OR p_decision<>btrim(p_decision)
     OR current_setting('aos.org_id',true) IS DISTINCT FROM p_org
     OR current_setting('aos.project_id',true) IS DISTINCT FROM p_project
     OR current_setting('transaction_isolation')<>'read committed'
     OR current_setting('transaction_read_only')<>'off' THEN
    RAISE EXCEPTION 'BUDGET_CONSUMER_IDENTITY_SCOPE_REQUIRED' USING ERRCODE='42501';
  END IF;
  IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname IN (session_user,current_user)
       AND (rolsuper OR rolinherit OR rolcreatedb OR rolcreaterole OR rolreplication OR rolbypassrls
         OR (rolname=current_user AND rolcanlogin)))
     OR EXISTS(SELECT 1 FROM pg_auth_members WHERE roleid IN(session_user::regrole,current_user::regrole)
       OR member IN(session_user::regrole,current_user::regrole)) THEN
    RAISE EXCEPTION 'BUDGET_CONSUMER_ROLE_DRIFT' USING ERRCODE='42501';
  END IF;
  -- Same exclusion key as the issuer. READ COMMITTED observes a committed revoke after waiting.
  PERFORM pg_advisory_xact_lock(hashtextextended('budget-cost-review:'||p_org||':'||p_project||':'||p_proposal,0));
  SELECT * INTO p FROM public.aip_budget_cost_proposal WHERE org_id=p_org AND project_id=p_project AND proposal_id=p_proposal;
  IF NOT FOUND OR p.status<>'proposed' OR p.source_verification<>'pending' OR p.activation_eligible
     OR public.aip_budget_cost_hash_a0v_126(jsonb_build_object('domain','aos.budget-cost-proposal/v1','proposal',p.payload))<>p.proposal_hash THEN
    RAISE EXCEPTION 'BUDGET_CONSUMER_PROPOSAL_DRIFT' USING ERRCODE='23514';
  END IF;
  request_hash:=public.aip_budget_cost_hash_a0v_126(jsonb_build_object('domain','aos.budget-cost-consume/v1',
    'tenant',jsonb_build_object('orgId',p_org,'projectId',p_project),'proposalId',p_proposal,
    'proposalHash',p.proposal_hash,'decisionId',p_decision));
  SELECT * INTO prior FROM public.aip_budget_receipt WHERE org_id=p_org AND project_id=p_project
    AND operation='budget_revision.activate_cost' AND idempotency_key=p_proposal;
  IF FOUND THEN
    IF prior.request_hash<>request_hash OR prior.result_ref->>'decisionId' IS DISTINCT FROM p_decision
       OR prior.result_ref->>'proposalId' IS DISTINCT FROM p_proposal
       OR prior.result_ref->>'receiptId' IS DISTINCT FROM prior.receipt_id
       OR NOT EXISTS(SELECT 1 FROM public.aip_budget_cost_runtime_fence f WHERE f.org_id=p_org AND f.project_id=p_project
          AND f.budget_id=prior.result_ref->>'resourceId' AND f.revision=(prior.result_ref->>'revision')::bigint AND f.decision_id=p_decision)
       OR NOT EXISTS(SELECT 1 FROM public.aip_budget_revision r WHERE r.org_id=p_org AND r.project_id=p_project
          AND r.budget_id=prior.result_ref->>'resourceId' AND r.revision=(prior.result_ref->>'revision')::bigint
          AND r.content_hash=prior.result_ref->>'contentHash' AND r.lifecycle='active') THEN
      RAISE EXCEPTION 'BUDGET_CONSUMER_RECEIPT_DRIFT' USING ERRCODE='23514';
    END IF;
    RETURN prior.result_ref;
  END IF;
  t:=p.payload->'target';basis:=p.payload->'basis';ref:=basis->'provider';
  FOREACH number_value IN ARRAY ARRAY[t->'revision',t->'dailyLimitMinor',t->'monthlyLimitMinor',t->'alertThresholdPct',
      p.payload->'draftRevision',p.payload->'expectedHeadVersion',basis->'perRequestRiskMinor',basis->'totalRiskMinor',basis->'maxRequests',ref->'revision'] LOOP
    IF (jsonb_typeof(number_value)='number' AND number_value::text ~ '^[1-9][0-9]*$'
        AND number_value::text::numeric<=9007199254740991) IS NOT TRUE THEN
      RAISE EXCEPTION 'BUDGET_CONSUMER_EXACT_INTEGER_REQUIRED' USING ERRCODE='23514';
    END IF;
  END LOOP;
  SELECT * INTO d FROM public.aip_budget_cost_decision WHERE org_id=p_org AND project_id=p_project
    AND proposal_id=p_proposal AND decision_id=p_decision;
  IF NOT FOUND OR d.decision<>'approved' OR d.proposal_hash<>p.proposal_hash OR d.actor_subject<>p.checker_subject
     OR d.expires_at<>p.expires_at OR d.source_ref IS DISTINCT FROM ref
     OR EXISTS(SELECT 1 FROM public.aip_budget_cost_revocation WHERE org_id=p_org AND project_id=p_project AND decision_id=p_decision) THEN
    RAISE EXCEPTION 'BUDGET_CONSUMER_APPROVAL_UNAVAILABLE' USING ERRCODE='42501';
  END IF;
  PERFORM subject FROM public.meta_membership WHERE org_id=p_org AND project_id=p_project
    AND subject IN(p.maker_subject,p.checker_subject) ORDER BY subject FOR SHARE;
  IF p.maker_subject=p.checker_subject OR (SELECT count(*) FROM public.meta_membership WHERE org_id=p_org
    AND project_id=p_project AND subject IN(p.maker_subject,p.checker_subject) AND lower(role) IN('owner','admin'))<>2 THEN
    RAISE EXCEPTION 'BUDGET_CONSUMER_CURRENT_MEMBER_REQUIRED' USING ERRCODE='42501';
  END IF;
  IF (p.payload->'schemaVersion'='1'::jsonb AND p.payload->'tenant'=jsonb_build_object('orgId',p_org,'projectId',p_project)
      AND p.payload->>'makerSubject'=p.maker_subject AND p.payload->>'checkerSubject'=p.checker_subject
      AND t->>'budgetId'=p.budget_id AND t->>'environment'='development' AND t->>'lifecycle'='active'
      AND t->>'currency'='CNY' AND t->'hardStop'='true'::jsonb AND t->>'unknownUsageBehavior'='block'
      AND p.payload->'accounts'=jsonb_build_object('daily',p.budget_id||':daily','pilot',p.budget_id||':pilot')
      AND p.payload->>'currency'='CNY' AND p.payload->'period'=jsonb_build_object('start',t->'effectiveFrom','end',t->'effectiveUntil')
      AND basis->>'kind'='development_risk_proposal' AND ref->>'assetType'='ProviderInstanceRevision'
      AND length(btrim(basis->>'providerModelId')) BETWEEN 1 AND 240
      AND (basis->>'perRequestRiskMinor')::numeric>0 AND (basis->>'maxRequests')::numeric>0
      AND (basis->>'perRequestRiskMinor')::numeric*(basis->>'maxRequests')::numeric<=(basis->>'totalRiskMinor')::numeric
      AND (basis->>'perRequestRiskMinor')::numeric<=(t->>'dailyLimitMinor')::numeric
      AND (basis->>'totalRiskMinor')::numeric<=(t->>'monthlyLimitMinor')::numeric) IS NOT TRUE THEN
    RAISE EXCEPTION 'BUDGET_CONSUMER_TARGET_INVALID' USING ERRCODE='23514';
  END IF;
  SELECT * INTO h FROM public.aip_budget_head WHERE org_id=p_org AND project_id=p_project AND budget_id=p.budget_id FOR UPDATE;
  IF NOT FOUND OR h.version<>(p.payload->>'expectedHeadVersion')::bigint
     OR h.current_revision<>(p.payload->>'draftRevision')::bigint OR (t->>'revision')::bigint<>h.current_revision+1 THEN
    RAISE EXCEPTION 'BUDGET_CONSUMER_HEAD_DRIFT' USING ERRCODE='23514';
  END IF;
  SELECT * INTO draft FROM public.aip_budget_revision WHERE org_id=p_org AND project_id=p_project
    AND budget_id=p.budget_id AND revision=h.current_revision;
  expected:=draft.payload-ARRAY['tenant','contentHash','createdBy','createdAt'];
  IF NOT FOUND OR draft.lifecycle<>'draft'
     OR public.aip_budget_cost_hash_a0v_126(expected)<>draft.content_hash
     OR (expected-ARRAY['revision','lifecycle','effectiveFrom','effectiveUntil']) IS DISTINCT FROM
        (t-ARRAY['revision','lifecycle','effectiveFrom','effectiveUntil'])
     OR draft.effective_from IS DISTINCT FROM (t->>'effectiveFrom')::timestamptz
     OR draft.effective_until IS DISTINCT FROM (t->>'effectiveUntil')::timestamptz THEN
    RAISE EXCEPTION 'BUDGET_CONSUMER_DRAFT_DRIFT' USING ERRCODE='23514';
  END IF;
  IF EXISTS(SELECT 1 FROM public.aip_capability_invocation WHERE org_id=p_org AND project_id=p_project
      AND policy_ref->>'resourceType'='BudgetRevision' AND policy_ref->>'resourceId'=p.budget_id)
     OR EXISTS(SELECT 1 FROM public.aip_budget_reservation WHERE org_id=p_org AND project_id=p_project
      AND policy_ref->>'resourceType'='BudgetRevision' AND policy_ref->>'resourceId'=p.budget_id)
     OR EXISTS(SELECT 1 FROM public.aip_budget_bucket WHERE org_id=p_org AND project_id=p_project
      AND ((bucket_kind='daily' AND account_id=p.budget_id||':daily') OR (bucket_kind='pilot' AND account_id=p.budget_id||':pilot'))) THEN
    RAISE EXCEPTION 'BUDGET_CONSUMER_LEDGER_NOT_EMPTY' USING ERRCODE='23514';
  END IF;
  SELECT current_revision INTO source_revision FROM public.aip_provider_instance_head WHERE org_id=p_org AND project_id=p_project
    AND provider_instance_id=ref->>'assetId' FOR SHARE;
  SELECT * INTO source FROM public.aip_provider_instance_revision WHERE org_id=p_org AND project_id=p_project
    AND provider_instance_id=ref->>'assetId' AND revision=source_revision;
  IF NOT FOUND OR (source_revision=(ref->>'revision')::bigint AND source.content_hash=ref->>'contentHash'
    AND source.lifecycle='active' AND source.payload->'tenant'=jsonb_build_object('orgId',p_org,'projectId',p_project)
    AND source.payload->>'providerInstanceId'=source.provider_instance_id AND (source.payload->>'revision')::bigint=source.revision
    AND source.payload->>'contentHash'=source.content_hash AND source.payload->>'lifecycle'='active'
    AND public.aip_budget_cost_hash_a0v_126(source.payload-ARRAY['tenant','revision','contentHash','createdBy','createdAt'])=source.content_hash) IS NOT TRUE THEN
    RAISE EXCEPTION 'BUDGET_CONSUMER_SOURCE_DRIFT' USING ERRCODE='23514';
  END IF;
  checked_at:=clock_timestamp();
  IF (checked_at<p.expires_at AND p.created_at<=d.created_at AND d.created_at<d.expires_at
      AND p.expires_at=least(p.created_at+interval '30 minutes',(t->>'effectiveUntil')::timestamptz)
      AND (t->>'effectiveFrom')::timestamptz<=checked_at AND checked_at<(t->>'effectiveUntil')::timestamptz) IS NOT TRUE THEN
    RAISE EXCEPTION 'BUDGET_CONSUMER_EXPIRED' USING ERRCODE='42501';
  END IF;
  target_hash:=public.aip_budget_cost_hash_a0v_126(t);
  payload:=t||jsonb_build_object('tenant',jsonb_build_object('orgId',p_org,'projectId',p_project),
    'contentHash',target_hash,'createdBy',p.maker_subject,'createdAt',checked_at);
  UPDATE public.aip_budget_head SET current_revision=(t->>'revision')::bigint,version=version+1,updated_at=checked_at
    WHERE org_id=p_org AND project_id=p_project AND budget_id=p.budget_id;
  INSERT INTO public.aip_budget_revision(org_id,project_id,budget_id,revision,content_hash,lifecycle,environment,currency,
    daily_limit_minor,monthly_limit_minor,alert_threshold_pct,hard_stop,unknown_usage_behavior,effective_from,effective_until,
    owner,over_budget_approver,payload,created_by,created_at)
    VALUES(p_org,p_project,p.budget_id,(t->>'revision')::bigint,target_hash,'active','development','CNY',
      (t->>'dailyLimitMinor')::bigint,(t->>'monthlyLimitMinor')::bigint,(t->>'alertThresholdPct')::bigint,true,'block',
      (t->>'effectiveFrom')::timestamptz,(t->>'effectiveUntil')::timestamptz,t->>'owner',t->>'overBudgetApprover',payload,p.maker_subject,checked_at);
  result:=jsonb_build_object('resourceType','BudgetRevision','resourceId',p.budget_id,'revision',(t->>'revision')::bigint,
    'contentHash',target_hash,'proposalId',p_proposal,'proposalHash',p.proposal_hash,'decisionId',p_decision,'receiptId','budget-cost-consume-'||request_hash);
  INSERT INTO public.aip_budget_receipt(org_id,project_id,receipt_id,operation,idempotency_key,request_hash,result_ref,created_by,created_at)
    VALUES(p_org,p_project,result->>'receiptId','budget_revision.activate_cost',p_proposal,request_hash,result,p.maker_subject,checked_at);
  INSERT INTO public.aip_budget_cost_runtime_fence(org_id,project_id,budget_id,revision,decision_id)
    VALUES(p_org,p_project,p.budget_id,(t->>'revision')::bigint,p_decision);
  IF clock_timestamp()>=p.expires_at OR clock_timestamp()>=(t->>'effectiveUntil')::timestamptz THEN
    RAISE EXCEPTION 'BUDGET_CONSUMER_EXPIRED' USING ERRCODE='42501';
  END IF;
  RETURN result;
END $function$

public.aip_budget_consumption_fact_a0v_1.definition:
CREATE OR REPLACE FUNCTION public.aip_budget_consumption_fact_a0v_128(p_org text, p_project text, p_proposal text, p_decision text, p_actor text, p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
    payload jsonb; expected jsonb; digest text; target_hash text;
    r public.aip_budget_receipt%ROWTYPE; v public.aip_budget_revision%ROWTYPE;
    d public.aip_budget_cost_decision%ROWTYPE;
BEGIN
    payload:=public.aip_budget_cost_actor_a0v_127(p_org,p_project,p_proposal,p_actor,p_hash);
    SELECT * INTO d FROM public.aip_budget_cost_decision WHERE org_id=p_org AND project_id=p_project
        AND proposal_id=p_proposal AND decision_id=p_decision;
    IF NOT FOUND OR d.decision<>'approved' OR d.proposal_hash IS DISTINCT FROM p_hash
       OR d.actor_subject IS DISTINCT FROM payload->>'checkerSubject'
       OR d.source_ref IS DISTINCT FROM payload->'basis'->'provider' THEN
        RAISE EXCEPTION 'BUDGET_RECONCILE_ORIGINAL_DECISION_REQUIRED' USING ERRCODE='42501';
    END IF;
    SELECT * INTO r FROM public.aip_budget_receipt WHERE org_id=p_org AND project_id=p_project
        AND operation='budget_revision.activate_cost' AND idempotency_key=p_proposal;
    IF NOT FOUND THEN RETURN jsonb_build_object('status','unresolved'); END IF;
    digest:=public.aip_budget_cost_hash_a0v_126(jsonb_build_object('domain','aos.budget-cost-consume/v1',
        'tenant',jsonb_build_object('orgId',p_org,'projectId',p_project),'proposalId',p_proposal,
        'proposalHash',p_hash,'decisionId',p_decision));
    target_hash:=public.aip_budget_cost_hash_a0v_126(payload->'target');
    expected:=jsonb_build_object('resourceType','BudgetRevision','resourceId',payload->'target'->>'budgetId',
        'revision',payload->'target'->'revision','contentHash',target_hash,'proposalId',p_proposal,
        'proposalHash',p_hash,'decisionId',p_decision,'receiptId','budget-cost-consume-'||digest);
    IF r.request_hash IS DISTINCT FROM digest OR r.receipt_id IS DISTINCT FROM expected->>'receiptId'
       OR r.created_by IS DISTINCT FROM p_actor OR r.result_ref IS DISTINCT FROM expected THEN
        RETURN jsonb_build_object('status','conflict');
    END IF;
    SELECT * INTO v FROM public.aip_budget_revision WHERE org_id=p_org AND project_id=p_project
        AND budget_id=expected->>'resourceId' AND revision::text=expected->>'revision';
    IF NOT FOUND OR v.lifecycle<>'active' OR v.content_hash IS DISTINCT FROM target_hash
       OR v.payload->'tenant' IS DISTINCT FROM jsonb_build_object('orgId',p_org,'projectId',p_project)
       OR v.payload->>'contentHash' IS DISTINCT FROM target_hash
       OR v.payload-ARRAY['tenant','contentHash','createdBy','createdAt'] IS DISTINCT FROM payload->'target'
       OR NOT EXISTS(SELECT 1 FROM public.aip_budget_cost_runtime_fence WHERE org_id=p_org AND project_id=p_project
            AND budget_id=v.budget_id AND revision=v.revision AND decision_id=p_decision) THEN
        RETURN jsonb_build_object('status','conflict');
    END IF;
    RETURN jsonb_build_object('status','observed','receipt',r.result_ref,'activationEligible',false);
END $function$

public.aip_cost_configuration_expected_a.definition:
CREATE OR REPLACE FUNCTION public.aip_cost_configuration_expected_a0v_128(p_org text, p_project text, p_proposal text, p_decision text, p_actor text, p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE fact jsonb; p jsonb; t jsonb; auth jsonb; price jsonb; policy jsonb; digest text;
 stamp jsonb; price_hash text; policy_hash text; budget_ref jsonb; result jsonb;
BEGIN
 fact:=public.aip_budget_consumption_fact_a0v_128(p_org,p_project,p_proposal,p_decision,p_actor,p_hash);
 IF fact->>'status' IS DISTINCT FROM 'observed' THEN
  RAISE EXCEPTION 'COST_CONFIGURATION_CONSUMED_SOURCE_REQUIRED' USING ERRCODE='42501'; END IF;
 p:=public.aip_budget_cost_actor_a0v_127(p_org,p_project,p_proposal,p_actor,p_hash);t:=p->'target';
 IF p->'basis'->>'kind' IS DISTINCT FROM 'development_risk_proposal' THEN
  RAISE EXCEPTION 'COST_CONFIGURATION_DEVELOPMENT_SOURCE_REQUIRED' USING ERRCODE='42501'; END IF;
 SELECT to_jsonb(to_char(created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) INTO stamp FROM public.aip_budget_receipt WHERE org_id=p_org AND project_id=p_project
  AND operation='budget_revision.activate_cost' AND idempotency_key=p_proposal;
 digest:=public.aip_budget_cost_hash_a0v_126(jsonb_build_object('domain','aos.budget-cost-configuration/v1',
  'tenant',p->'tenant','proposalId',p_proposal,'proposalHash',p_hash,'decisionId',p_decision));
 auth:=jsonb_build_object('tenant',p->'tenant','provider',p->'basis'->'provider',
  'providerModelId',p->'basis'->'providerModelId','approvalRef',p_decision,'environment','development',
  'effectiveFrom',t->'effectiveFrom','effectiveUntil',t->'effectiveUntil');
 price:=jsonb_build_object('priceSnapshotId','cost-price-'||digest,'currency','CNY',
  'inputTokenPrice',NULL,'outputTokenPrice',NULL,'cachedTokenPrice',NULL,'tokenUnit',1000,
  'effectiveFrom',t->'effectiveFrom','effectiveUntil',t->'effectiveUntil','lifecycle','active','developmentCostAuthorization',auth);
 price_hash:=public.aip_budget_cost_hash_a0v_126(price);
 price:=price||jsonb_build_object('tenant',p->'tenant','revision',1,'contentHash',price_hash,'createdBy',p_actor,'createdAt',stamp);
 budget_ref:=jsonb_build_object('assetType','BudgetRevision','assetId',t->'budgetId','revision',t->'revision',
  'contentHash',fact->'receipt'->'contentHash');
 policy:=jsonb_build_object('policyId','cost-policy-'||digest,'revision',1,'environment','development',
  'effectiveFrom',t->'effectiveFrom','effectiveUntil',t->'effectiveUntil','owner',t->'owner','approvalRef',p_decision,
  'lifecycle','active','developmentCostAuthorization',auth,'budgetRevisionRef',budget_ref,'currency','CNY',
  'hardStop',true,'unknownUsageBehavior','block','unknownPriceBehavior','block','allowZeroPrice',false,'zeroPriceApprovalRef',NULL);
 policy_hash:=public.aip_budget_cost_hash_a0v_126(policy);
 policy:=policy||jsonb_build_object('tenant',p->'tenant','contentHash',policy_hash,'createdBy',p_actor,'createdAt',stamp);
 result:=jsonb_build_object('proposalId',p_proposal,'proposalHash',p_hash,'decisionId',p_decision,
  'budgetRef',budget_ref,'priceRef',jsonb_build_object('assetType','ModelPriceSnapshotRevision',
   'assetId',price->'priceSnapshotId','revision',1,'contentHash',price_hash),
  'policyRef',jsonb_build_object('assetType','BudgetPolicyRevision','assetId',policy->'policyId','revision',1,'contentHash',policy_hash),
  'receiptId','cost-configuration-'||digest);
 RETURN jsonb_build_object('price',price,'policy',policy,'receipt',result,'requestHash',digest);
END $function$

public.aip_cost_configuration_fact_a0v_1.definition:
CREATE OR REPLACE FUNCTION public.aip_cost_configuration_fact_a0v_128(p_org text, p_project text, p_proposal text, p_decision text, p_actor text, p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE expected jsonb; r public.aip_model_governance_policy_receipt%ROWTYPE; price jsonb; policy jsonb;
BEGIN
 expected:=public.aip_cost_configuration_expected_a0v_128(p_org,p_project,p_proposal,p_decision,p_actor,p_hash);
 SELECT * INTO r FROM public.aip_model_governance_policy_receipt WHERE org_id=p_org AND project_id=p_project
  AND operation='budget_cost.configure' AND idempotency_key=p_proposal;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','unresolved'); END IF;
 IF r.request_hash IS DISTINCT FROM expected->>'requestHash' OR r.result_ref IS DISTINCT FROM expected->'receipt'
  OR r.receipt_id IS DISTINCT FROM expected->'receipt'->>'receiptId' OR r.created_by IS DISTINCT FROM p_actor THEN
  RETURN jsonb_build_object('status','conflict'); END IF;
 SELECT payload INTO price FROM public.aip_model_price_snapshot_revision WHERE org_id=p_org AND project_id=p_project
  AND model_price_snapshot_id=expected->'price'->>'priceSnapshotId' AND revision=1
  AND content_hash=expected->'price'->>'contentHash' AND lifecycle='active';
 SELECT payload INTO policy FROM public.aip_model_governance_policy_revision WHERE org_id=p_org AND project_id=p_project
  AND policy_kind='budget' AND policy_id=expected->'policy'->>'policyId' AND revision=1
  AND content_hash=expected->'policy'->>'contentHash' AND lifecycle='active';
 IF price IS DISTINCT FROM expected->'price' OR policy IS DISTINCT FROM expected->'policy' THEN
  RETURN jsonb_build_object('status','conflict'); END IF;
 RETURN jsonb_build_object('status','observed','receipt',r.result_ref,'activationEligible',false);
END $function$

public.aip_configure_budget_cost_a0v_128.definition:
CREATE OR REPLACE FUNCTION public.aip_configure_budget_cost_a0v_128(p_org text, p_project text, p_proposal text, p_decision text, p_actor text, p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE p jsonb; t jsonb; ref jsonb; e jsonb; prior jsonb; price jsonb; policy jsonb;
 h public.aip_budget_head%ROWTYPE; source public.aip_provider_instance_revision%ROWTYPE;
 source_revision bigint; deadline timestamptz; now_at timestamptz;
BEGIN
 IF current_setting('transaction_read_only')<>'off' OR current_setting('transaction_isolation')<>'read committed' THEN
  RAISE EXCEPTION 'COST_CONFIGURATION_WRITE_TRANSACTION_REQUIRED' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('budget-cost-review:'||p_org||':'||p_project||':'||p_proposal,0));
 prior:=public.aip_cost_configuration_fact_a0v_128(p_org,p_project,p_proposal,p_decision,p_actor,p_hash);
 IF prior->>'status'='observed' THEN RETURN prior; END IF;
 IF prior->>'status' IS DISTINCT FROM 'unresolved' THEN
  RAISE EXCEPTION 'COST_CONFIGURATION_RECEIPT_CONFLICT' USING ERRCODE='23514'; END IF;
 p:=public.aip_budget_cost_actor_a0v_127(p_org,p_project,p_proposal,p_actor,p_hash);t:=p->'target';ref:=p->'basis'->'provider';
 PERFORM subject FROM public.meta_membership WHERE org_id=p_org AND project_id=p_project
  AND subject IN(p_actor,p->>'checkerSubject') ORDER BY subject FOR SHARE;
 IF (SELECT count(*) FROM public.meta_membership WHERE org_id=p_org AND project_id=p_project
  AND subject IN(p_actor,p->>'checkerSubject') AND lower(role) IN('owner','admin'))<>2 THEN
  RAISE EXCEPTION 'COST_CONFIGURATION_CURRENT_MEMBERS_REQUIRED' USING ERRCODE='42501'; END IF;
 SELECT expires_at INTO deadline FROM public.aip_budget_cost_decision WHERE org_id=p_org AND project_id=p_project
  AND decision_id=p_decision AND proposal_id=p_proposal;
 IF EXISTS(SELECT 1 FROM public.aip_budget_cost_revocation WHERE org_id=p_org AND project_id=p_project AND decision_id=p_decision) THEN
  RAISE EXCEPTION 'COST_CONFIGURATION_REVOKED' USING ERRCODE='42501'; END IF;
 SELECT * INTO h FROM public.aip_budget_head WHERE org_id=p_org AND project_id=p_project AND budget_id=t->>'budgetId' FOR SHARE;
 IF NOT FOUND OR h.current_revision IS DISTINCT FROM (t->>'revision')::bigint
  OR h.version IS DISTINCT FROM (p->>'expectedHeadVersion')::bigint+1 THEN
  RAISE EXCEPTION 'COST_CONFIGURATION_BUDGET_HEAD_DRIFT' USING ERRCODE='23514'; END IF;
 SELECT current_revision INTO source_revision FROM public.aip_provider_instance_head WHERE org_id=p_org AND project_id=p_project
  AND provider_instance_id=ref->>'assetId' FOR SHARE;
 SELECT * INTO source FROM public.aip_provider_instance_revision WHERE org_id=p_org AND project_id=p_project
  AND provider_instance_id=ref->>'assetId' AND revision=source_revision;
 IF NOT FOUND OR (source_revision=(ref->>'revision')::bigint AND source.content_hash=ref->>'contentHash'
  AND source.lifecycle='active' AND source.payload->'tenant'=p->'tenant'
  AND source.payload->>'providerInstanceId'=source.provider_instance_id AND source.payload->>'lifecycle'='active'
  AND source.payload->>'contentHash'=source.content_hash AND (source.payload->>'revision')::bigint=source_revision
  AND public.aip_budget_cost_hash_a0v_126(source.payload-ARRAY['tenant','revision','contentHash','createdBy','createdAt'])=source.content_hash) IS NOT TRUE THEN
  RAISE EXCEPTION 'COST_CONFIGURATION_PROVIDER_DRIFT' USING ERRCODE='23514'; END IF;
 now_at:=clock_timestamp();
 IF (now_at<deadline AND (t->>'effectiveFrom')::timestamptz<=now_at AND now_at<(t->>'effectiveUntil')::timestamptz) IS NOT TRUE THEN
  RAISE EXCEPTION 'COST_CONFIGURATION_EXPIRED' USING ERRCODE='42501'; END IF;
 e:=public.aip_cost_configuration_expected_a0v_128(p_org,p_project,p_proposal,p_decision,p_actor,p_hash);price:=e->'price';policy:=e->'policy';
 INSERT INTO public.aip_model_price_snapshot_head(org_id,project_id,model_price_snapshot_id,current_revision,version)
  VALUES(p_org,p_project,price->>'priceSnapshotId',1,1);
 INSERT INTO public.aip_model_price_snapshot_revision(org_id,project_id,model_price_snapshot_id,revision,content_hash,lifecycle,payload,created_by,created_at)
  VALUES(p_org,p_project,price->>'priceSnapshotId',1,price->>'contentHash','active',price,p_actor,(price->>'createdAt')::timestamptz);
 INSERT INTO public.aip_model_governance_policy_head(org_id,project_id,policy_kind,policy_id,current_revision,version)
  VALUES(p_org,p_project,'budget',policy->>'policyId',1,1);
 INSERT INTO public.aip_model_governance_policy_revision(org_id,project_id,policy_kind,policy_id,revision,content_hash,lifecycle,
  effective_from,effective_until,payload,created_by,created_at)
  VALUES(p_org,p_project,'budget',policy->>'policyId',1,policy->>'contentHash','active',
   (policy->>'effectiveFrom')::timestamptz,(policy->>'effectiveUntil')::timestamptz,policy,p_actor,(policy->>'createdAt')::timestamptz);
 INSERT INTO public.aip_model_governance_policy_receipt(org_id,project_id,receipt_id,operation,idempotency_key,request_hash,result_ref,created_by)
  VALUES(p_org,p_project,e->'receipt'->>'receiptId','budget_cost.configure',p_proposal,e->>'requestHash',e->'receipt',p_actor);
 IF clock_timestamp()>=deadline OR clock_timestamp()>=(t->>'effectiveUntil')::timestamptz THEN
  RAISE EXCEPTION 'COST_CONFIGURATION_EXPIRED' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('status','observed','receipt',e->'receipt','activationEligible',false);
END $function$

public.canonical_asset_registry_jsonb(js.definition:
CREATE OR REPLACE FUNCTION public.canonical_asset_registry_jsonb(input_value jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE STRICT
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
        DECLARE
          value_type TEXT;
          rendered TEXT;
        BEGIN
          value_type := jsonb_typeof(input_value);
          CASE value_type
            WHEN 'object' THEN
              SELECT '{' || COALESCE(
                       string_agg(
                         to_jsonb(item.key)::TEXT || ':' ||
                           canonical_asset_registry_jsonb(item.value),
                         ',' ORDER BY item.key COLLATE "C"
                       ),
                       ''
                     ) || '}'
                INTO rendered
                FROM jsonb_each(input_value) AS item;
              RETURN rendered;
            WHEN 'array' THEN
              SELECT '[' || COALESCE(
                       string_agg(
                         canonical_asset_registry_jsonb(item.value),
                         ',' ORDER BY item.ordinality
                       ),
                       ''
                     ) || ']'
                INTO rendered
                FROM jsonb_array_elements(input_value)
                     WITH ORDINALITY AS item(value, ordinality);
              RETURN rendered;
            WHEN 'number' THEN
              rendered := input_value::TEXT;
              IF POSITION('.' IN rendered) > 0 THEN
                rendered := (rendered::DOUBLE PRECISION)::TEXT;
                IF POSITION('.' IN rendered) = 0
                   AND POSITION('e' IN rendered) = 0 THEN
                  rendered := rendered || '.0';
                END IF;
              END IF;
              RETURN rendered;
            ELSE
              RETURN input_value::TEXT;
          END CASE;
        END;
        $function$

